import { update_department } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_department, {
          input: {
            department_id: this.rowInfo.department_id,
            department_status: "DEACTIVE"
          }
        }));
        var response = JSON.parse(result.data.update_department);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message || "Failed to delete department");
        }
      } catch (error) {
        console.error("Error deleting department:", error);
        const errorMessage = error.errors && error.errors[0] ? error.errors[0].message : "Failed to delete department. Please try again.";
        this.$emit("errorMsg", errorMessage);
      } finally {
        this.loading = false;
      }
    }
  }
};
